'AC-extraction.120.1'; from __future__ import annotations; from decimal import Decimal; from src.extraction.base.validation import detect_balance_chain_break; _clean_chain_payload = lambda: {'institution': 'DBS', 'currency': 'SGD', 'period_start': '2025-01-01', 'period_end': '2025-01-31', 'opening_balance': '1000.00', 'closing_balance': '1600.00', 'transactions': [{'date': '2025-01-05', 'amount': '500.00', 'direction': 'IN', 'balance_after': '1500.00'}, {'date': '2025-01-10', 'amount': '200.00', 'direction': 'OUT', 'balance_after': '1300.00'}, {'date': '2025-01-20', 'amount': '300.00', 'direction': 'IN', 'balance_after': '1600.00'}]}
def _dropped_row_payload() -> dict: payload = _clean_chain_payload(); payload['transactions'] = [{'date': '2025-01-05', 'amount': '500.00', 'direction': 'IN', 'balance_after': '1500.00'}, {'date': '2025-01-20', 'amount': '300.00', 'direction': 'IN', 'balance_after': '1300.00'}]; return payload
def test_AC13_20_1_detector_finds_break_index_on_dropped_row(): 'AC-extraction.120.1'; payload = _dropped_row_payload(); result = detect_balance_chain_break(payload['transactions']); assert result is not None; assert result.index == 1; assert result.expected_balance == Decimal('1800.00'); assert result.observed_balance == Decimal('1300.00')
def test_AC13_20_2_clean_chain_reports_no_break(): 'AC-extraction.120.2'; payload = _clean_chain_payload(); assert detect_balance_chain_break(payload['transactions']) is None
def test_AC13_20_3_detector_is_decimal_tolerant(): 'AC-extraction.120.3'; txns = [{'date': '2025-01-05', 'amount': '0.10', 'direction': 'IN', 'balance_after': '1000.10'}, {'date': '2025-01-06', 'amount': '0.20', 'direction': 'IN', 'balance_after': '1000.35'}]; assert detect_balance_chain_break(txns, opening_balance=Decimal('1000.00')) is None; txns[1]['balance_after'] = '1000.80'; broken = detect_balance_chain_break(txns, opening_balance=Decimal('1000.00')); assert broken is not None and broken.index == 1; _m1_txns = [{'date': '2025-01-05', 'amount': '500.00', 'direction': 'IN', 'balance_after': '1400.00'}]; _m1_result = detect_balance_chain_break(_m1_txns, opening_balance=Decimal('1000.00')); assert _m1_result is not None and _m1_result.index == 0
